body.query:
query Network($key: ID!, $predicate: Predicate) {
  network(key: $key) {
    key
    title
    description
    deleted
    created
    homepage
    prose {
      ...NetworkAboutTab
    }
    numConstituents
  }
  occurrenceSearch(predicate: $predicate) {
    documents(size: 0) {
      total
    }
  }
  literatureSearch(gbifNetworkKey: [$key]) {
    documents {
      total
    }
  }
}

fragment NetworkAboutTab on NetworkProse {
  title
  summary
  excerpt
  body
  primaryImage {
    ...ArticleBanner
  }
  primaryLink {
    label
    url
  }
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}
